ACTUAL="$(sha256sum "$ZIP" | awk '{print $1}')"
[[ "$ACTUAL" == "$EXPECTED_ZIP_SHA256" ]] || die "embedded ZIP SHA mismatch: $ACTUAL"
python3 - "$ZIP" "$TMP" <<'PY'
import sys,zipfile
z,d=sys.argv[1:]
with zipfile.ZipFile(z) as f:
    bad=f.testzip()
    if bad: raise SystemExit('ZIP CRC fail: '+bad)
    names=f.namelist()
    if not names or any(n.startswith('/') or '..' in n.split('/') for n in names): raise SystemExit('unsafe ZIP path')
    f.extractall(d)
print('ZIP_CRC_AND_PATHS=PASS')
PY
[[ -d "$SRC" ]] || die "source root nova3000 없음"
( cd "$SRC" && sha256sum -c SOURCE_MANIFEST.sha256 >/dev/null ) || die "SOURCE_MANIFEST 검증 실패"
echo "SOURCE_MANIFEST=PASS"

say "2/15 Ground-up contract preflight"
python3 - "$SRC" <<'PY'
from pathlib import Path
import json,sys
r=Path(sys.argv[1])
assert (r/'Dockerfile').read_text().startswith('FROM python:3.12-slim-bookworm')
text='\n'.join(p.read_text(errors='ignore') for p in list((r/'app').rglob('*.py'))+list((r/'static').rglob('*')) if p.is_file())
for bad in ('docker commit','main.py.bak','ROOT-MEMORY-LIVENESS','CLEAN-RUNTIME-R1.'):
    assert bad not in text,bad
j=json.loads((r/'SIGNAL_POLICY_FROZEN.json').read_text())
assert j['policy']=='ENTRY_V18_TRUTH_GUARD_MAX_PROFIT'
assert j['pressure_score']==62 and j['direct']['score']==75 and j['cooldown_sec']==600
ws=(r/'app/broker/websocket.py').read_text(); kw=(r/'app/broker/kiwoom.py').read_text(); cfg=(r/'app/config.py').read_text()
assert "'trnm':'REMOVE'" in ws and '_remove_group' in ws and "'refresh':'1'" in ws
assert 'removed=sorted(old_set-new_set)' in ws and 'added=[x for x in items if x not in old_set]' in ws
assert 'expires_dt' in kw and '_token_expiry_epoch' in kw and 'invalidate' in kw and 'r.status_code in (401,403)' in kw
assert 'effective_ws_code_budget' in cfg and 'ws_session_item_cap' in cfg and 'max(0.205' in cfg
print('GROUNDUP_BROKER_SAFETY=PASS')
print('GROUNDUP_CONTRACT=PASS')
PY

say "3/15 Existing active + host safety preflight"
if sudo docker inspect "$CONTAINER" >/dev/null 2>&1; then OLD_EXISTS=1; fi
[[ $OLD_EXISTS -eq 1 ]] || die "기존 quant-nova 컨테이너 없음 — 안전 rollback 기준선이 필요합니다."
OLD_STATUS="$(sudo docker inspect -f '{{.State.Status}}' "$CONTAINER")"
[[ "$OLD_STATUS" == "running" ]] || die "기존 quant-nova가 running 상태가 아님: $OLD_STATUS"
OLD_IMAGE_ID="$(sudo docker inspect -f '{{.Image}}' "$CONTAINER")"
DATA_KB="$(du -sk "$DATA_DIR" | awk '{print $1}')"
FREE_KB="$(df -Pk "$APP_DIR" | awk 'NR==2{print $4}')"
NEED_KB=$((DATA_KB + 1400000))
(( FREE_KB > NEED_KB )) || die "디스크 여유 부족: free=${FREE_KB}KB need>${NEED_KB}KB"
printf 'OLD_IMAGE_ID=%s\nOLD_STATUS=%s\nDATA_KB=%s\nFREE_KB=%s\n' "$OLD_IMAGE_ID" "$OLD_STATUS" "$DATA_KB" "$FREE_KB"

say "4/15 Freeze old active — no rename/delete/mutation"
timeout 20 sudo docker stop -t 8 "$CONTAINER" >/dev/null 2>&1 || sudo docker kill "$CONTAINER" >/dev/null 2>&1 || die "기존 active 정지 실패"
[[ "$(sudo docker inspect -f '{{.State.Running}}' "$CONTAINER")" == "false" ]] || die "기존 active가 아직 실행 중"
OLD_STOPPED=1
for _ in $(seq 1 30); do AVAIL_MB="$(free -m | awk '/Mem:/{print $7}')"; (( AVAIL_MB >= 280 )) && break; sleep 1; done
(( AVAIL_MB >= 280 )) || die "기존 active 정지 후 available RAM ${AVAIL_MB}MB < 280MB"
echo "OLD_ACTIVE_FROZEN=PASS available=${AVAIL_MB}MB"

say "5/15 Frozen production-data snapshot"
mkdir -p "$CAND_DATA"
cp -a --no-preserve=ownership "$DATA_DIR"/. "$CAND_DATA"/
mkdir -p "$CAND_DATA/nova30"
echo "DATA_SNAPSHOT=PASS size=$(du -sh "$CAND_DATA" | awk '{print $1}')"

say "6/15 Clean Docker build from Python base — no previous NOVA image inheritance"
export DOCKER_BUILDKIT=1
sudo docker build --pull --no-cache -t "$IMAGE" "$SRC"
IMAGE_ID="$(sudo docker image inspect -f '{{.Id}}' "$IMAGE")"
[[ -n "$IMAGE_ID" ]] || die "clean image build 실패"
PARENT="$(sudo docker image inspect -f '{{json .Config.Labels}}' "$IMAGE" 2>/dev/null || true)"
echo "CLEAN_IMAGE=$IMAGE_ID"

NET_ARGS=()
if sudo docker network inspect "$NETWORK" >/dev/null 2>&1; then NET_ARGS=(--network "$NETWORK"); fi
UIDGID="$(id -u):$(id -g)"
COMMON=(--read-only --tmpfs /tmp:rw,noexec,nosuid,size=32m --user "$UIDGID" --env-file "$ENV_FILE" -e NOVA_DATA_DIR=/app/data/nova30 -e NOVA_LEGACY_DATA_DIR=/app/data --pids-limit 256 --security-opt no-new-privileges --cap-drop ALL --log-driver json-file --log-opt max-size=10m --log-opt max-file=3)

say "7/15 Isolated candidate + production-data copy"
sudo docker rm -f "$CANDIDATE" >/dev/null 2>&1 || true
sudo docker run -d --name "$CANDIDATE" "${NET_ARGS[@]}" "${COMMON[@]}" --memory=384m --memory-swap=384m --memory-reservation=256m -e NOVA_CANDIDATE_MODE=1 -e NOVA_OFFLINE=0 -v "$CAND_DATA:/app/data" "$IMAGE" >/dev/null
for _ in $(seq 1 120); do
  if sudo docker exec "$CANDIDATE" python -c "import json,urllib.request,sys;j=json.load(urllib.request.urlopen('http://127.0.0.1:8000/api/readyz',timeout=2));sys.exit(0 if j.get('ok') else 1)" >/dev/null 2>&1; then break; fi
  sleep .5
done
sudo docker exec "$CANDIDATE" python -c "import json,urllib.request;j=json.load(urllib.request.urlopen('http://127.0.0.1:8000/api/readyz',timeout=2));assert j.get('ok'),j;print('CANDIDATE_READYZ=PASS',j)"
sudo docker exec "$CANDIDATE" env PYTHONPATH=/app python /app/scripts/runtime_smoke.py --clients 10 --ready-timeout 10
sudo docker exec "$CANDIDATE" env PYTHONPATH=/app python /app/scripts/master_audit.py
sudo docker exec "$CANDIDATE" env PYTHONPATH=/app python /app/scripts/validate.py --quick
CMEM="$(sudo docker inspect -f '{{.HostConfig.Memory}} {{.HostConfig.MemorySwap}}' "$CANDIDATE")"
[[ "$(awk '{print $1}' <<<"$CMEM")" == "$(awk '{print $2}' <<<"$CMEM")" ]] || die "candidate no-swap cgroup 불일치: $CMEM"

say "8/15 Candidate 60-second memory/journal/UI soak"
sudo docker exec -i "$CANDIDATE" python - <<'PY'
import json,os,time,urllib.request
TOKEN=os.getenv('APP_ACCESS_TOKEN','').strip()
def get(path):
    h={'X-App-Token':TOKEN} if TOKEN else {}
    with urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:8000'+path,headers=h),timeout=3) as r:return json.load(r)
rss=[]
for i in range(30):
    j=get('/api/realtime-health');m=j.get('memory') or {};t=j.get('telemetry') or {};w=j.get('journal') or {}
    assert j.get('ok'),j
    assert float(m.get('swap_mb') or 0)==0,m
    assert float(m.get('rss_mb') or 0)<350,m
    assert int(w.get('db_init_fail') or 0)==0,w
    assert int(w.get('important_enqueue_fail') or 0)==0,w
    assert int(w.get('wal_hard_stall_exit') or 0)==0,w
    assert int(w.get('event_hard_stall_exit') or 0)==0,w
    for k in ('dropped_signal_tick_count','signal_price_mismatch_count','wrong_venue_price_count','signal_without_live_snapshot_count','dispatch_handler_error_count'):
        assert int(t.get(k) or 0)==0,(k,t.get(k))
    assert int(j.get('trade_errors') or 0)==0,j.get('trade_errors')
    assert int(j.get('coalesce_errors') or 0)==0,j.get('coalesce_errors')
    rss.append(float(m.get('rss_mb') or 0));time.sleep(2)
print('CANDIDATE_SOAK=PASS',{'rss_start':rss[0],'rss_end':rss[-1],'rss_max':max(rss)})
PY
[[ "$(sudo docker inspect -f '{{.State.OOMKilled}}' "$CANDIDATE")" == "false" ]] || die "candidate OOMKilled"
[[ "$(sudo docker inspect -f '{{.RestartCount}}' "$CANDIDATE")" == "0" ]] || die "candidate restarted"
sudo docker rm -f "$CANDIDATE" >/dev/null

say "9/15 Atomic cutover — old container preserved as immutable rollback"
sudo docker rename "$CONTAINER" "$BACKUP"; OLD_RENAMED=1
sudo docker run -d --name "$CONTAINER" "${NET_ARGS[@]}" "${COMMON[@]}" --restart unless-stopped --memory=448m --memory-swap=448m --memory-reservation=320m -e NOVA_CANDIDATE_MODE=0 -e NOVA_OFFLINE=0 -p "${HOST_PORT}:8000" -v "$DATA_DIR:/app/data" "$IMAGE" >/dev/null
NEW_STARTED=1
for _ in $(seq 1 120); do
  if curl -fsS --max-time 2 "http://127.0.0.1:${HOST_PORT}/api/livez" >/dev/null 2>&1; then break; fi
  sleep .5
done
curl -fsS --max-time 3 "http://127.0.0.1:${HOST_PORT}/api/livez" | python3 -c 'import json,sys;j=json.load(sys.stdin);assert j.get("ok"),j;assert j.get("version")=="NOVA-3.0.0-MASTER-GROUNDUP-4",j;print("ACTIVE_LIVEZ=PASS",j)'
for _ in $(seq 1 80); do
  sudo docker exec "$CONTAINER" python -c "import json,urllib.request,sys;j=json.load(urllib.request.urlopen('http://127.0.0.1:8000/api/readyz',timeout=2));sys.exit(0 if j.get('ok') else 1)" >/dev/null 2>&1 && break
  sleep .5
done
sudo docker exec "$CONTAINER" python -c "import json,urllib.request;j=json.load(urllib.request.urlopen('http://127.0.0.1:8000/api/readyz',timeout=2));assert j.get('ok'),j;print('ACTIVE_READYZ=PASS',j)"
AMEM="$(sudo docker inspect -f '{{.HostConfig.Memory}} {{.HostConfig.MemorySwap}}' "$CONTAINER")"
[[ "$(awk '{print $1}' <<<"$AMEM")" == "$(awk '{print $2}' <<<"$AMEM")" ]] || die "active no-swap cgroup 불일치: $AMEM"

say "10/15 Active HTTP + UI WebSocket contract"
sudo docker exec "$CONTAINER" env PYTHONPATH=/app python /app/scripts/runtime_smoke.py --clients 10 --ready-timeout 10
curl -fsS --max-time 3 "http://127.0.0.1:${HOST_PORT}/" >/dev/null
echo "HOST_PORT_HTTP=PASS"

say "11/15 Real Kiwoom feed gate when market session is active"
MARKET_ACTIVE="$(sudo docker exec "$CONTAINER" python -c "from app.runtime.clock import sessions;print('1' if sessions()['active'] else '0')")"
if [[ "$MARKET_ACTIVE" == "1" ]]; then
  OK=0
  for _ in $(seq 1 120); do
    SESSION_NOW="$(sudo docker exec "$CONTAINER" python -c "from app.runtime.clock import sessions;print('1' if sessions()['active'] else '0')")"
    if [[ "$SESSION_NOW" != "1" ]]; then OK=2; break; fi
    if sudo docker exec -i "$CONTAINER" python - <<'PY' >/dev/null 2>&1
import json,os,time,urllib.request
T=os.getenv('APP_ACCESS_TOKEN','').strip();h={'X-App-Token':T} if T else {}
with urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:8000/api/realtime-health',headers=h),timeout=3) as r:j=json.load(r)
w=j.get('ws') or {};m=j.get('memory') or {};t=j.get('telemetry') or {}
assert j.get('feed_state')=='LIVE',j.get('feed_state')
assert w.get('connected') and w.get('logged_in') and int(w.get('registered') or 0)>0,w
assert time.time()-float(w.get('last_message_at') or 0)<8,w
assert float(w.get('last_trade_at') or 0)>0 and time.time()-float(w.get('last_trade_at') or 0)<30,w
assert float(m.get('swap_mb') or 0)==0,m
for k in ('dropped_signal_tick_count','dispatch_handler_error_count','pinned_ws_overflow'):
    assert int(t.get(k) or 0)==0,(k,t.get(k))
assert int(j.get('trade_errors') or 0)==0,j.get('trade_errors')
assert int(j.get('coalesce_errors') or 0)==0,j.get('coalesce_errors')
PY
    then OK=1; break; fi
    sleep 2
  done
  if [[ $OK -eq 1 ]]; then REAL_FEED_RESULT="PASS"; echo "REAL_FEED_GATE=$REAL_FEED_RESULT";
  elif [[ $OK -eq 2 ]]; then REAL_FEED_RESULT="SKIP_SESSION_ENDED_DURING_GATE"; echo "REAL_FEED_GATE=$REAL_FEED_RESULT";
  else die "실장중 Kiwoom WS/Feed LIVE gate 실패"; fi
else
  REAL_FEED_RESULT="SKIP_MARKET_CLOSED"; echo "REAL_FEED_GATE=$REAL_FEED_RESULT"
fi

say "12/15 Five-minute full-worker hard gate"
sudo docker exec -i "$CONTAINER" python - <<'PY'
import json,os,time,urllib.request,statistics
T=os.getenv('APP_ACCESS_TOKEN','').strip();H={'X-App-Token':T} if T else {}
def get():
    with urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:8000/api/realtime-health',headers=H),timeout=3) as r:return json.load(r)
rss=[];start=time.time()
for i in range(60):
    j=get();m=j.get('memory') or {};t=j.get('telemetry') or {};w=j.get('journal') or {}
    assert j.get('ok'),j
    assert float(m.get('swap_mb') or 0)==0,m
    assert float(m.get('rss_mb') or 0)<420,m
    assert float(j.get('event_loop_lag_p95_ms') or 0)<300,j.get('event_loop_lag_p95_ms')
    assert float(j.get('trade_queue_oldest_age_ms') or 0)<1000,j.get('trade_queue_oldest_age_ms')
    for k in ('dropped_signal_tick_count','signal_price_mismatch_count','wrong_venue_price_count','signal_without_live_snapshot_count','dispatch_handler_error_count','pinned_ws_overflow'):
        assert int(t.get(k) or 0)==0,(k,t.get(k))
    assert int(j.get('trade_errors') or 0)==0,j.get('trade_errors')
    assert int(j.get('coalesce_errors') or 0)==0,j.get('coalesce_errors')
    for k in ('db_init_fail','important_enqueue_fail','wal_hard_stall_exit','event_hard_stall_exit'):
        assert int(w.get(k) or 0)==0,(k,w.get(k))
    rss.append(float(m.get('rss_mb') or 0));time.sleep(5)
first=statistics.mean(rss[:12]);last=statistics.mean(rss[-12:])
assert last-first<100,(first,last,max(rss))
print('ACTIVE_5MIN_SOAK=PASS',{'rss_first60_avg':round(first,1),'rss_last60_avg':round(last,1),'rss_max':max(rss),'seconds':round(time.time()-start)})
PY
[[ "$(sudo docker inspect -f '{{.State.OOMKilled}}' "$CONTAINER")" == "false" ]] || die "active OOMKilled"
[[ "$(sudo docker inspect -f '{{.RestartCount}}' "$CONTAINER")" == "0" ]] || die "active restarted during gate"

say "13/15 Static UI atomic guard sync"
if [[ -d "$GUARD_STATIC" ]]; then
  mkdir -p "$GUARD_BK"
  sudo cp -a "$GUARD_STATIC"/. "$GUARD_BK"/
  GUARD_BACKUP_READY=1
  for f in index.html nova.js nova.css manifest.webmanifest sw.js; do
    [[ -f "$SRC/static/$f" ]] || continue
    sudo cp "$SRC/static/$f" "$GUARD_STATIC/.$f.nova30.tmp"
    sudo chmod 644 "$GUARD_STATIC/.$f.nova30.tmp"
    sudo mv "$GUARD_STATIC/.$f.nova30.tmp" "$GUARD_STATIC/$f"
  done
  sudo rm -f "$GUARD_CACHE"/* >/dev/null 2>&1 || true
  echo "HTTP_GUARD_STATIC_SYNC=PASS"
else
  echo "HTTP_GUARD_STATIC_SYNC=SKIP(no guard static dir)"
fi
for helper in nova-http-guard kiwoom-caddy; do
  if sudo docker inspect "$helper" >/dev/null 2>&1; then
    [[ "$(sudo docker inspect -f '{{.State.Running}}' "$helper")" == "true" ]] || die "$helper not running"
    echo "$helper=RUNNING"
  fi
done

say "14/15 Deployment seal"
mkdir -p "$DEPLOY_DIR"
cat > "$DEPLOY_DIR/DEPLOYMENT_OK.txt" <<EOF
status=PASS
version=$APP_VERSION
revision=$REV
source_zip_sha256=$EXPECTED_ZIP_SHA256
image=$IMAGE
image_id=$IMAGE_ID
previous_container=$BACKUP
previous_image_id=$OLD_IMAGE_ID
clean_build=YES
previous_image_inheritance=NO
in_container_source_patch=NO
docker_commit=NO
production_data_snapshot=PASS
candidate_ready=PASS
candidate_runtime_smoke_10_clients=PASS
candidate_no_swap=PASS
active_ready=PASS
active_runtime_smoke_10_clients=PASS
active_no_swap=PASS
real_feed_gate=$REAL_FEED_RESULT
active_5min_soak=PASS
completed_at=$(date -Is)
EOF

say "15/15 Final status"
sudo docker ps --filter "name=^/${CONTAINER}$" --format 'table {{.Names}}\t{{.Image}}\t{{.Status}}\t{{.Ports}}'
sudo docker exec -i "$CONTAINER" python - <<'PY'
import json,os,urllib.request
T=os.getenv('APP_ACCESS_TOKEN','').strip();H={'X-App-Token':T} if T else {}
with urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:8000/api/realtime-health',headers=H),timeout=3) as r:j=json.load(r)
print(json.dumps({'version':j.get('version'),'feed_state':j.get('feed_state'),'memory':j.get('memory'),'load_mode':j.get('load_mode'),'ws':j.get('ws'),'journal':j.get('journal')},ensure_ascii=False))
PY
SUCCESS=1
rm -rf "$TMP"
trap - EXIT
echo "=== QUANT NOVA 3.0.0 MASTER GROUND-UP 4 DEPLOY PASS ==="
echo "ROLLBACK_CONTAINER_PRESERVED=$BACKUP"
